package com.oms.inventory.service.impl;

import com.fasterxml.jackson.databind.*;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;
import javax.annotation.Resource;
import java.math.*;
import java.util.*;

/** Inventory conversion boundary: one local transaction consumes inputs and receives outputs. */
@Service public class StockProcessService {
 @Resource JdbcTemplate jdbc;
 private static final ObjectMapper JSON=new ObjectMapper().configure(SerializationFeature.ORDER_MAP_ENTRIES_BY_KEYS,true);
 private static void require(boolean b,String m){if(!b)throw new IllegalArgumentException(m);}
 static long n(Map<String,Object> m,String k){Object v=m.get(k);return v==null?0:new BigDecimal(v.toString()).longValueExact();}
 static String s(Map<String,Object> m,String k){return Objects.toString(m.get(k),"");}
 static Map<String,Object> map(Object... a){Map<String,Object> r=new LinkedHashMap<>();for(int i=0;i<a.length;i+=2)r.put(a[i].toString(),a[i+1]);return r;}
 static String encode(Object v){try{return JSON.writeValueAsString(v);}catch(Exception e){throw new IllegalArgumentException("加工数据无法编码");}}
 @SuppressWarnings("unchecked") static Map<String,Object> object(Object v){try{return v instanceof Map?(Map<String,Object>)v:JSON.readValue(v.toString(),Map.class);}catch(Exception e){throw new IllegalArgumentException("加工快照缺失或损坏");}}
 @SuppressWarnings("unchecked") static List<Map<String,Object>> rows(Object v){require(v instanceof List,"加工明细缺失");return (List<Map<String,Object>>)v;}
 private Map<String,Object> one(String sql,Object... a){List<Map<String,Object>> r=jdbc.queryForList(sql,a);require(r.size()==1,"加工记录或库存来源不存在");return r.get(0);}
 private String hex(byte[] data){StringBuilder out=new StringBuilder();for(byte b:data)out.append(String.format("%02x",b));return out.toString();}
 private String digest(Object o){try{return hex(java.security.MessageDigest.getInstance("SHA-256").digest(encode(o).getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalArgumentException(e);}}
 private void identity(String c,String sn){require(c!=null&&c.matches("[A-Z0-9_-]{1,50}")&&sn!=null&&sn.matches("JG[a-zA-Z0-9_-]{1,62}"),"加工公司或单号无效");}
 private void lockSkus(String c,Collection<String> skus){for(String sku:new TreeSet<>(skus)){jdbc.update("INSERT INTO oms_inventory(company_code,sku_sn,total_stock,available_stock,version) VALUES (?,?,0,0,1) ON DUPLICATE KEY UPDATE id=id",c,sku);one("SELECT * FROM oms_inventory WHERE company_code=? AND sku_sn=? FOR UPDATE",c,sku);}}
 public Map<String,Object> origin(String c,long batch){Map<String,Object> r=one("SELECT o.*,b.sku_sn,b.store_code,b.batch_code,b.zp_available_number FROM oms_stock_process_origin o JOIN wms_inventory_batch b ON b.company_code=o.company_code AND b.id=o.batch_id WHERE o.company_code=? AND o.batch_id=?",c,batch);r.put("recipe",object(r.remove("recipe_json")));return r;}
 public Map<String,Object> report(String c,String sn){Map<String,Object> r=one("SELECT * FROM oms_stock_process WHERE company_code=? AND process_sn=?",c,sn);r.put("recipe",object(r.remove("recipe_json")));r.put("holds",jdbc.queryForList("SELECT h.*,b.batch_code,b.transaction_price FROM oms_stock_process_hold h JOIN wms_inventory_batch b ON b.company_code=h.company_code AND b.id=h.batch_id WHERE h.company_code=? AND h.process_sn=? ORDER BY h.sku_sn,h.batch_id",c,sn));r.put("events",jdbc.queryForList("SELECT id,message_id,result_json,create_time FROM oms_stock_process_event WHERE company_code=? AND process_sn=? ORDER BY id",c,sn));return r;}
 public List<Map<String,Object>> batches(String c,String sku,String store){return jdbc.queryForList("SELECT b.id,b.batch_code,b.zp_available_number,o.process_sn FROM wms_inventory_batch b JOIN oms_stock_process_origin o ON o.company_code=b.company_code AND o.batch_id=b.id WHERE b.company_code=? AND b.sku_sn=? AND b.store_code=? AND b.zp_available_number>0 ORDER BY b.id LIMIT 100",c,sku,store);}
 @Transactional(rollbackFor=Exception.class,isolation=Isolation.READ_COMMITTED,timeout=30)
 public Map<String,Object> execute(String c,String action,Map<String,Object> cmd){cmd=object(encode(cmd));String sn=s(cmd,"process_sn");identity(c,sn);require(Arrays.asList("reserve","post","release").contains(action),"加工库存动作无效");
  Map<String,Object> recipe="reserve".equals(action)?object(cmd.get("recipe")):object(one("SELECT recipe_json FROM oms_stock_process WHERE company_code=? AND process_sn=?",c,sn).get("recipe_json"));
  String parent=s(recipe,"sku_sn");List<Map<String,Object>> components=rows(recipe.get("components"));require(!parent.trim().isEmpty()&&!components.isEmpty()&&components.size()<=50,"加工组成无效");TreeSet<String> skus=new TreeSet<>();skus.add(parent);for(Map<String,Object> line:components){require(!s(line,"sku_sn").trim().isEmpty()&&!parent.equals(s(line,"sku_sn"))&&n(line,"quantity")>0&&n(line,"quantity")<=100000&&skus.add(s(line,"sku_sn")),"加工组件重复或配比无效");}lockSkus(c,skus);
  if("reserve".equals(action))reserve(c,sn,cmd,recipe);else{Map<String,Object> task=one("SELECT * FROM oms_stock_process WHERE company_code=? AND process_sn=? FOR UPDATE",c,sn);if("release".equals(action))release(c,sn,task);else post(c,sn,task,cmd,components);}
  for(String sku:skus)OrderStockService.replanPending(jdbc,c,sku);return report(c,sn);
 }
 private void reserve(String c,String sn,Map<String,Object> cmd,Map<String,Object> recipe){String hash=digest(cmd);List<Map<String,Object>> old=jdbc.queryForList("SELECT * FROM oms_stock_process WHERE company_code=? AND process_sn=? FOR UPDATE",c,sn);if(!old.isEmpty()){require(hash.equals(s(old.get(0),"request_hash")),"重复加工占用的参数变化");return;}
  long qty=n(cmd,"quantity");String op=s(cmd,"operation"),store=s(cmd,"store_code"),parent=s(recipe,"sku_sn");require(qty>0&&qty<=100000000&&Arrays.asList("ASSEMBLE","DISASSEMBLE").contains(op)&&!store.trim().isEmpty()&&store.length()<=64,"加工类型、数量或仓库无效");require("STOCKED".equals(s(recipe,"inventory_mode")),"仅实物套装可执行组装拆卸");
  Map<String,Long> needed=new TreeMap<>();if("ASSEMBLE".equals(op))for(Map<String,Object> part:rows(recipe.get("components")))needed.put(s(part,"sku_sn"),Math.multiplyExact(qty,n(part,"quantity")));else{Map<String,Object> origin=origin(c,n(cmd,"source_batch_id"));require(parent.equals(s(origin,"sku_sn"))&&store.equals(s(origin,"store_code"))&&encode(recipe).equals(encode(origin.get("recipe"))),"拆卸必须使用原组装批次与组成快照");needed.put(parent,qty);}
  jdbc.update("INSERT INTO oms_stock_process(company_code,process_sn,store_code,operation,sku_sn,quantity,recipe_json,request_hash) VALUES (?,?,?,?,?,?,?,?)",c,sn,store,op,parent,qty,encode(recipe),hash);
  for(Map.Entry<String,Long> item:needed.entrySet()){String sku=item.getKey();long left=item.getValue();require(left<=100000000,"组件数量超过上限");Map<String,Object> balance=one("SELECT * FROM oms_inventory WHERE company_code=? AND sku_sn=?",c,sku);Map<String,Object> wh=one("SELECT * FROM wms_inventory WHERE company_code=? AND sku_sn=? AND store_code=? FOR UPDATE",c,sku,store);consistent(c,sku,store);
   require(n(balance,"available_stock")>=left&&n(wh,"zp_available_number")-OrderStockService.publicClaims(jdbc,c,sku,Arrays.asList(store))>=left,"扣除渠道锁库、订单预占和待占需求后，加工可用库存不足："+sku);
   String batchFilter="DISASSEMBLE".equals(op)?" AND id="+n(cmd,"source_batch_id"):"";
   for(Map<String,Object> batch:jdbc.queryForList("SELECT * FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=? AND zp_available_number>0"+batchFilter+" ORDER BY id FOR UPDATE",c,sku,store)){long take=Math.min(left,n(batch,"zp_available_number"));if(take==0)continue;jdbc.update("UPDATE wms_inventory_batch SET zp_available_number=zp_available_number-?,zp_lock_number=zp_lock_number+?,version=version+1 WHERE id=?",take,take,batch.get("id"));jdbc.update("INSERT INTO oms_stock_process_hold(company_code,process_sn,batch_id,sku_sn,quantity) VALUES (?,?,?,?,?)",c,sn,batch.get("id"),sku,take);journal(c,sn,"PROCESS_LOCK",sn,batch,0,"ZP");left-=take;if(left==0)break;}require(left==0,"加工批次可用库存不足");
   jdbc.update("UPDATE wms_inventory SET zp_available_number=zp_available_number-?,zp_lock_number=zp_lock_number+?,version=version+1 WHERE id=?",item.getValue(),item.getValue(),wh.get("id"));jdbc.update("UPDATE oms_inventory SET available_stock=available_stock-?,allocated_stock=allocated_stock+?,version=version+1 WHERE company_code=? AND sku_sn=?",item.getValue(),item.getValue(),c,sku);
  }
 }
 private void release(String c,String sn,Map<String,Object> task){if("STOPPED".equals(s(task,"state")))return;for(Map<String,Object> h:jdbc.queryForList("SELECT h.*,b.batch_code FROM oms_stock_process_hold h JOIN wms_inventory_batch b ON b.company_code=h.company_code AND b.id=h.batch_id WHERE h.company_code=? AND h.process_sn=? ORDER BY h.sku_sn,h.batch_id FOR UPDATE",c,sn)){long left=n(h,"quantity")-n(h,"consumed_quantity")-n(h,"released_quantity");if(left==0)continue;Map<String,Object> before=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=? FOR UPDATE",c,h.get("batch_id"));require(n(before,"zp_lock_number")>=left,"加工原批次占用不足");jdbc.update("UPDATE wms_inventory_batch SET zp_lock_number=zp_lock_number-?,zp_available_number=zp_available_number+?,version=version+1 WHERE id=?",left,left,h.get("batch_id"));jdbc.update("UPDATE wms_inventory SET zp_lock_number=zp_lock_number-?,zp_available_number=zp_available_number+?,version=version+1 WHERE company_code=? AND sku_sn=? AND store_code=?",left,left,c,h.get("sku_sn"),task.get("store_code"));jdbc.update("UPDATE oms_inventory SET allocated_stock=allocated_stock-?,available_stock=available_stock+?,version=version+1 WHERE company_code=? AND sku_sn=?",left,left,c,h.get("sku_sn"));jdbc.update("UPDATE oms_stock_process_hold SET released_quantity=released_quantity+? WHERE company_code=? AND process_sn=? AND batch_id=?",left,c,sn,h.get("batch_id"));journal(c,sn,"PROCESS_RELEASE",sn,before,0,"ZP");}
  jdbc.update("UPDATE oms_stock_process SET state='STOPPED' WHERE company_code=? AND process_sn=?",c,sn);
 }
 private void post(String c,String sn,Map<String,Object> task,Map<String,Object> cmd,List<Map<String,Object>> components){String message=s(cmd,"message_id");require(!message.trim().isEmpty()&&message.length()<=100,"加工回传消息标识无效");Map<String,Object> identity=new LinkedHashMap<>(cmd);identity.remove("reviewed");String hash=digest(identity);List<Map<String,Object>> prior=jdbc.queryForList("SELECT * FROM oms_stock_process_event WHERE company_code=? AND process_sn=? AND message_id=?",c,sn,message);if(!prior.isEmpty()){require(hash.equals(s(prior.get(0),"payload_hash")),"同一加工消息内容冲突");return;}boolean stopped="STOPPED".equals(s(task,"state"));require(!stopped||Boolean.TRUE.equals(cmd.get("reviewed")),"加工剩余已停止，迟到回传须人工核实实际消耗和产出");long qty=n(cmd,"quantity");require(qty>0&&n(task,"completed_quantity")+qty<=n(task,"quantity"),"加工完成数量超过计划剩余");
  List<Map<String,Object>> inputs=rows(cmd.get("inputs")),outputs=rows(cmd.get("outputs"));require(!inputs.isEmpty()&&!outputs.isEmpty()&&inputs.size()<=500&&outputs.size()<=500,"加工回传投入和产出明细无效");boolean assemble="ASSEMBLE".equals(s(task,"operation")),review=Boolean.TRUE.equals(cmd.get("reviewed"));Map<String,Long> expected=new TreeMap<>();for(Map<String,Object> p:components)expected.put(s(p,"sku_sn"),Math.multiplyExact(qty,n(p,"quantity")));Map<String,Long> inSum=sum(inputs),outSum=sum(outputs);Map<String,Long> parent=Collections.singletonMap(s(task,"sku_sn"),qty);
  require((assemble?outSum:inSum).equals(parent),"成品实际数量必须与本次完成套数一致");require((assemble?inSum:outSum).keySet().equals(expected.keySet())||review&&expected.keySet().containsAll((assemble?inSum:outSum).keySet()),"回传含未知组件或缺少组件");require(review||(assemble?inSum:outSum).equals(expected),"加工投入产出与配比不符，需要人工核对");
  Map<String,BigDecimal> costs=new TreeMap<>();BigDecimal total=BigDecimal.ZERO;String store=s(task,"store_code");Set<String> checked=new HashSet<>();
  for(Map<String,Object> line:inputs){String sku=s(line,"sku_sn");long q=n(line,"quantity");require(q>0&&"ZP".equals(s(line,"inventory_type"))&&!s(line,"batch_code").trim().isEmpty(),"投入必须是带批次的正品库存");if(checked.add(sku))consistent(c,sku,store);
   Map<String,Object> hold=one("SELECT h.*,b.* FROM oms_stock_process_hold h JOIN wms_inventory_batch b ON b.id=h.batch_id AND b.company_code=h.company_code WHERE h.company_code=? AND h.process_sn=? AND h.sku_sn=? AND b.batch_code=? FOR UPDATE",c,sn,sku,line.get("batch_code"));long recovered=q-(n(hold,"quantity")-n(hold,"consumed_quantity")-n(hold,"released_quantity"));if(stopped&&review&&recovered>0){Map<String,Object> balance=one("SELECT * FROM oms_inventory WHERE company_code=? AND sku_sn=?",c,sku);Map<String,Object> wh=one("SELECT * FROM wms_inventory WHERE company_code=? AND sku_sn=? AND store_code=? FOR UPDATE",c,sku,store);require(n(hold,"released_quantity")>=recovered&&n(hold,"zp_available_number")>=recovered&&n(balance,"available_stock")>=recovered&&n(wh,"zp_available_number")-OrderStockService.publicClaims(jdbc,c,sku,Arrays.asList(store))>=recovered,"原批次释放库存已被使用或预占，请先解除库存冲突再确认迟到加工结果");jdbc.update("UPDATE wms_inventory_batch SET zp_available_number=zp_available_number-?,zp_lock_number=zp_lock_number+?,version=version+1 WHERE id=?",recovered,recovered,hold.get("batch_id"));jdbc.update("UPDATE wms_inventory SET zp_available_number=zp_available_number-?,zp_lock_number=zp_lock_number+?,version=version+1 WHERE company_code=? AND sku_sn=? AND store_code=?",recovered,recovered,c,sku,store);jdbc.update("UPDATE oms_inventory SET available_stock=available_stock-?,allocated_stock=allocated_stock+?,version=version+1 WHERE company_code=? AND sku_sn=?",recovered,recovered,c,sku);jdbc.update("UPDATE oms_stock_process_hold SET released_quantity=released_quantity-? WHERE company_code=? AND process_sn=? AND batch_id=?",recovered,c,sn,hold.get("batch_id"));journal(c,sn,"PROCESS_LOCK",message,hold,0,"ZP");hold.put("released_quantity",n(hold,"released_quantity")-recovered);hold.put("zp_available_number",n(hold,"zp_available_number")-recovered);hold.put("zp_lock_number",n(hold,"zp_lock_number")+recovered);}require(n(hold,"quantity")-n(hold,"consumed_quantity")-n(hold,"released_quantity")>=q&&n(hold,"zp_lock_number")>=q,"实际消耗超过原批次加工占用");line.put("unit_cost",hold.get("transaction_price"));BigDecimal amount=new BigDecimal(hold.get("transaction_price").toString()).multiply(BigDecimal.valueOf(q));costs.merge(sku,amount,BigDecimal::add);total=total.add(amount);
   jdbc.update("UPDATE wms_inventory_batch SET zp_actual_number=zp_actual_number-?,zp_lock_number=zp_lock_number-?,version=version+1 WHERE id=?",q,q,hold.get("batch_id"));jdbc.update("UPDATE wms_inventory SET zp_actual_number=zp_actual_number-?,zp_lock_number=zp_lock_number-?,version=version+1 WHERE company_code=? AND sku_sn=? AND store_code=?",q,q,c,sku,store);require(jdbc.update("UPDATE oms_inventory SET total_stock=total_stock-?,allocated_stock=allocated_stock-?,version=version+1 WHERE company_code=? AND sku_sn=? AND total_stock>=? AND allocated_stock>=?",q,q,c,sku,q,q)==1,"加工公司投入余额不足");jdbc.update("UPDATE oms_stock_process_hold SET consumed_quantity=consumed_quantity+? WHERE company_code=? AND process_sn=? AND batch_id=?",q,c,sn,hold.get("batch_id"));journal(c,sn,"PROCESS_OUT",message,hold,-q,"ZP");
  }
  Map<String,Object> weights=assemble?Collections.emptyMap():object(one("SELECT o.cost_json FROM oms_stock_process_origin o JOIN oms_stock_process_hold h ON h.company_code=o.company_code AND h.batch_id=o.batch_id WHERE h.company_code=? AND h.process_sn=?",c,sn).get("cost_json"));BigDecimal weightTotal=BigDecimal.ZERO;if(!assemble)for(Map<String,Object> line:outputs)weightTotal=weightTotal.add(new BigDecimal(Objects.toString(weights.get(s(line,"sku_sn")),"0")).multiply(BigDecimal.valueOf(n(line,"quantity"))));require(assemble||weightTotal.signum()>0||total.signum()==0,"拆卸成本分配依据缺失");
  BigDecimal valued=BigDecimal.ZERO;Map<String,Object> outputCosts=new TreeMap<>();if(assemble)for(String sku:costs.keySet())outputCosts.put(sku,costs.get(sku).divide(BigDecimal.valueOf(inSum.get(sku)),8,RoundingMode.HALF_UP).toPlainString());
  for(Map<String,Object> line:outputs){String sku=s(line,"sku_sn"),type=s(line,"inventory_type"),batch=s(line,"batch_code");long q=n(line,"quantity");require(q>0&&q<=100000000&&!batch.trim().isEmpty()&&batch.length()<=128&&Arrays.asList("ZP","CC","CP","JS","XS").contains(type),"产出批次、良次品或数量无效");boolean good="ZP".equals(type);BigDecimal price=assemble?total.divide(BigDecimal.valueOf(qty),2,RoundingMode.HALF_UP):weightTotal.signum()==0?BigDecimal.ZERO:total.multiply(new BigDecimal(weights.get(sku).toString())).divide(weightTotal,2,RoundingMode.HALF_UP);line.put("unit_cost",price);valued=valued.add(price.multiply(BigDecimal.valueOf(q)));receive(c,sn,message,store,sku,batch,q,good,price);Map<String,Object> b=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=? AND batch_code=?",c,sku,store,batch);if(assemble){List<Map<String,Object>> origins=jdbc.queryForList("SELECT * FROM oms_stock_process_origin WHERE company_code=? AND batch_id=?",c,b.get("id"));require(origins.isEmpty()||sn.equals(s(origins.get(0),"process_sn"))&&encode(object(origins.get(0).get("cost_json"))).equals(encode(outputCosts)),"成品批次来源或组件成本不同，请使用新的产出批次");jdbc.update("INSERT INTO oms_stock_process_origin(company_code,batch_id,process_sn,recipe_json,cost_json) VALUES (?,?,?,?,?) ON DUPLICATE KEY UPDATE batch_id=batch_id",c,b.get("id"),sn,task.get("recipe_json"),encode(outputCosts));}}
  Map<String,Object> result=map("quantity",qty,"inputs",inputs,"outputs",outputs,"input_cost",total,"output_cost",valued,"rounding_difference",valued.subtract(total));jdbc.update("INSERT INTO oms_stock_process_event(company_code,process_sn,message_id,payload_hash,result_json) VALUES (?,?,?,?,?)",c,sn,message,hash,encode(result));long next=n(task,"completed_quantity")+qty;if(next==n(task,"quantity"))release(c,sn,task);jdbc.update("UPDATE oms_stock_process SET completed_quantity=?,state=? WHERE company_code=? AND process_sn=?",next,next==n(task,"quantity")?"COMPLETED":stopped?"STOPPED":"PARTIAL",c,sn);
 }
 private Map<String,Long> sum(List<Map<String,Object>> lines){Map<String,Long> result=new TreeMap<>();for(Map<String,Object> l:lines){require(n(l,"quantity")>0,"加工实际数量须大于0");result.merge(s(l,"sku_sn"),n(l,"quantity"),Math::addExact);}return result;}
 private void receive(String c,String sn,String message,String store,String sku,String batch,long q,boolean good,BigDecimal price){jdbc.update("INSERT INTO wms_inventory(company_code,sku_sn,store_code,version) VALUES (?,?,?,1) ON DUPLICATE KEY UPDATE id=id",c,sku,store);consistent(c,sku,store);jdbc.update("INSERT INTO wms_inventory_batch(company_code,sku_sn,store_code,batch_code,transaction_price,version) VALUES (?,?,?,?,?,1) ON DUPLICATE KEY UPDATE id=id",c,sku,store,batch,price);Map<String,Object> before=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=? AND batch_code=? FOR UPDATE",c,sku,store,batch);require(new BigDecimal(before.get("transaction_price").toString()).compareTo(price)==0,"同批次产出成本不同，请使用独立批次");String prefix=good?"zp":"cp";jdbc.update("UPDATE wms_inventory_batch SET "+prefix+"_actual_number="+prefix+"_actual_number+?,"+prefix+"_available_number="+prefix+"_available_number+?,version=version+1 WHERE id=?",q,q,before.get("id"));jdbc.update("UPDATE wms_inventory SET "+prefix+"_actual_number="+prefix+"_actual_number+?,"+prefix+"_available_number="+prefix+"_available_number+?,version=version+1 WHERE company_code=? AND sku_sn=? AND store_code=?",q,q,c,sku,store);jdbc.update("UPDATE oms_inventory SET total_stock=total_stock+?,available_stock=available_stock+?,frozen_stock=frozen_stock+?,version=version+1 WHERE company_code=? AND sku_sn=?",q,good?q:0,good?0:q,c,sku);journal(c,sn,"PROCESS_IN",message,before,q,good?"ZP":"CP");if(good)jdbc.update("INSERT INTO oms_allocation_stock_signal(company_code,sku_sn,store_code) VALUES (?,?,?) ON DUPLICATE KEY UPDATE revision=revision+1,update_time=NOW()",c,sku,store);}
 private void consistent(String c,String sku,String store){Map<String,Object> wh=one("SELECT * FROM wms_inventory WHERE company_code=? AND sku_sn=? AND store_code=? FOR UPDATE",c,sku,store);for(String prefix:Arrays.asList("zp","cp")){Map<String,Object> total=one("SELECT COALESCE(SUM("+prefix+"_actual_number),0) actual,COALESCE(SUM("+prefix+"_available_number),0) available,COALESCE(SUM("+prefix+"_lock_number),0) locked FROM wms_inventory_batch WHERE company_code=? AND sku_sn=? AND store_code=?",c,sku,store);require(n(wh,prefix+"_actual_number")==n(total,"actual")&&n(wh,prefix+"_available_number")==n(total,"available")&&n(wh,prefix+"_lock_number")==n(total,"locked")&&n(total,"actual")==n(total,"available")+n(total,"locked"),"加工仓库汇总与批次库存不一致");}}
 private void journal(String c,String sn,String op,String request,Map<String,Object> before,long q,String type){Map<String,Object> after=one("SELECT * FROM wms_inventory_batch WHERE company_code=? AND id=?",c,before.get("id"));List<Object> args=new ArrayList<>(Arrays.asList(c,before.get("store_code"),before.get("sku_sn"),before.get("id"),before.get("batch_code"),type,op,request.length()>64?sn:request,sn,q,"套装加工",0,"WMS"));StringBuilder cols=new StringBuilder("company_code,store_code,sku_sn,batch_id,batch_code,inventory_type,operation_type,request_id,relation_sn,change_quantity,change_reason,operator_id,operator_name");for(String key:Arrays.asList("zp_actual_number","cp_actual_number","zp_available_number","cp_available_number","zp_lock_number","cp_lock_number")){cols.append(",old_").append(key).append(",new_").append(key);args.add(before.get(key));args.add(after.get(key));}jdbc.update("INSERT INTO wms_inventory_change_history("+cols+") VALUES ("+String.join(",",Collections.nCopies(args.size(),"?"))+")",args.toArray());}
}
